class TokenRule:
    def accepts(self, tokens, rule):
        self._validate(tokens, rule)
        token_index = 0
        rule_index = 0
        wildcard_index = -1
        retry_token = 0

        while token_index < len(tokens):
            if rule_index < len(rule) and (
                rule[rule_index] is None
                or rule[rule_index] == tokens[token_index]
            ):
                token_index += 1
                rule_index += 1
            elif rule_index < len(rule) and rule[rule_index] is Ellipsis:
                wildcard_index = rule_index
                retry_token = token_index + 1
                rule_index += 1
            elif wildcard_index != -1:
                retry_token += 1
                token_index = retry_token
                rule_index = wildcard_index + 1
            else:
                return False

        while rule_index < len(rule) and rule[rule_index] is Ellipsis:
            rule_index += 1
        return rule_index == len(rule)

    @staticmethod
    def _validate(tokens, rule):
        if type(tokens) is not list or type(rule) is not list:
            raise TypeError("tokens and rule must be lists")
        for token in tokens:
            if type(token) is not str:
                raise TypeError("tokens must contain strings")
            if not token:
                raise ValueError("tokens cannot contain empty strings")
        for part in rule:
            if part is None or part is Ellipsis:
                continue
            if type(part) is not str:
                raise TypeError("invalid rule element")
            if not part:
                raise ValueError("rule cannot contain empty literals")

